mapper.select:
select count(1)
from audit_event
where tenant_id = #{tenantId}
  and app_id = #{appId}

  and user_id = #{userId}


  and event_type = #{eventType}


  and entity_type = #{entityType}


  and entity_id = #{entityId}

select id,
       tenant_id,
       app_id,
       user_id,
       trace_id,
       request_id,
       event_type,
       source_service,
       entity_type,
       entity_id,
       payload_json,
       created_at
from audit_event
where tenant_id = #{tenantId}
  and app_id = #{appId}

  and user_id = #{userId}


  and event_type = #{eventType}


  and entity_type = #{entityType}


  and entity_id = #{entityId}

order by created_at desc, id desc
limit #{limit}
offset #{offset}
